package com.sodi.metareports.metaaccount; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import com.sodi.metareports.audit.AuditService; import java.util.*; import org.junit.jupiter.api.Test; import org.springframework.jdbc.core.JdbcTemplate;
class AssetServiceTest { @Test void recognizesCampaignWithoutPrefix(){var service=new AssetService(mock(JdbcTemplate.class),mock(AuditService.class));assertThat(service.validatePrefix(UUID.randomUUID()," ")).isEqualTo("CAMPAIGN_WITHOUT_PREFIX");} @Test void normalizesAndRejectsInvalidPrefix(){var service=new AssetService(mock(JdbcTemplate.class),mock(AuditService.class));assertThatThrownBy(()->service.addPrefix(UUID.randomUUID()," bad prefix ","")).isInstanceOf(IllegalArgumentException.class);} }
